cssRules.cssText:
.h-earth-3d-renderer-mount [data-h-earth-material-role], .h-earth-3d-renderer-mount [data-h-earth-material] { color: var(
      --h-earth-renderer-material-stroke,
      currentColor
    ); border-color: var(
      --h-earth-renderer-material-stroke,
      transparent
    ); background-color: var(
      --h-earth-renderer-material-fill,
      transparent
    ); }

.h-earth-3d-renderer-mount > [data-h-earth-source-preview-root="true"], .h-earth-3d-renderer-mount > .h-earth-source-preview-root { z-index: 1; background: radial-gradient(
      circle at 70% 18%,
      rgba(198, 224, 230, 0.12),
      transparent 28%
    ),
    linear-gradient(
      180deg,
      var(--h-earth-preview-sky-top),
      var(--h-earth-preview-sky-bottom) 46%,
      rgba(5, 16, 20, 0.94) 100%
    ); box-shadow: rgba(0, 0, 0, 0.34) 0px 0px 110px inset; }

.h-earth-3d-renderer-mount .h-earth-material-wet-sand { border-radius: 44% 48% 10% 10% / 26% 28% 12% 12%; border-color: rgba(184, 170, 135, 0.22); background: radial-gradient(
      ellipse at 28% 38%,
      rgba(220, 210, 174, 0.08),
      transparent 22%
    ),
    radial-gradient(
      ellipse at 71% 57%,
      rgba(216, 229, 224, 0.06),
      transparent 20%
    ),
    linear-gradient(
      180deg,
      rgba(91, 90, 77, 0.94),
      var(--h-earth-preview-wet-sand)
    ); }

.h-earth-3d-renderer-mount .h-earth-material-dry-sand { border-radius: 46% 46% 14% 14% / 42% 42% 18% 18%; border-color: rgba(226, 205, 159, 0.25); background: linear-gradient(
      180deg,
      rgba(195, 169, 121, 0.9),
      var(--h-earth-preview-dry-sand)
    ); }

.h-earth-3d-renderer-mount .h-earth-material-foam { border-radius: 999px; border-color: rgba(247, 255, 253, 0.52); background: linear-gradient(
      90deg,
      rgba(240, 250, 248, 0.62),
      var(--h-earth-preview-foam),
      rgba(227, 243, 240, 0.55)
    ); box-shadow: rgba(221, 242, 238, 0.18) 0px 0px 18px; }

.h-earth-3d-renderer-mount .h-earth-material-water { border-radius: 10% 10% 2% 2% / 20% 20% 4% 4%; border-color: rgba(120, 192, 215, 0.22); background: radial-gradient(
      ellipse at 50% 4%,
      var(--h-earth-preview-water-light),
      transparent 44%
    ),
    linear-gradient(
      180deg,
      rgba(52, 121, 145, 0.84),
      var(--h-earth-preview-water)
    ); }

.h-earth-3d-renderer-mount .h-earth-material-air-haze { border: 0px; border-radius: 0px; background: radial-gradient(
      ellipse at 52% 40%,
      rgba(160, 211, 224, 0.12),
      transparent 48%
    ),
    linear-gradient(
      180deg,
      var(--h-earth-preview-air),
      transparent 76%
    ); box-shadow: none; pointer-events: none; }

.h-earth-3d-renderer-mount .h-earth-material-manor-context { border-radius: 16% 16% 5% 5%; border-color: rgba(209, 190, 156, 0.26); background: linear-gradient(
      90deg,
      rgba(69, 62, 53, 0.94),
      var(--h-earth-preview-structure),
      rgba(65, 58, 49, 0.95)
    ); clip-path: polygon(6% 100%, 8% 48%, 20% 48%, 20% 26%, 34% 26%, 34% 42%, 48% 42%, 48% 15%, 63% 15%, 63% 39%, 78% 39%, 78% 54%, 94% 54%, 96% 100%); }

.h-earth-3d-renderer-mount .h-earth-material-jagged-rock, .h-earth-3d-renderer-mount .h-earth-material-distant-rock { border-color: var(--h-earth-preview-rock-edge); background: linear-gradient(
      145deg,
      rgba(89, 96, 93, 0.95),
      var(--h-earth-preview-rock)
    ); clip-path: polygon(4% 100%, 12% 48%, 26% 34%, 37% 6%, 48% 31%, 61% 17%, 71% 45%, 84% 32%, 96% 100%); }

@media (max-width: 640px) {
  :root { --h-earth-stage-min-height: 420px; }
  .h-earth-3d-route-root { padding: max(10px, env(safe-area-inset-top))
      10px
      max(24px, env(safe-area-inset-bottom)); }
  .h-earth-3d-shell { gap: 14px; }
  .h-earth-3d-public-header, .h-earth-3d-arrival-copy, .h-earth-3d-arrival-note, .h-earth-3d-public-control-strip, .h-earth-3d-world-shell, .h-earth-3d-panel, .h-earth-3d-readout-card, .h-earth-3d-layer-4-status-card, .h-earth-3d-target-drawer, .h-earth-3d-developer-drawer { border-radius: 20px; }
  .h-earth-3d-brand-mark { width: 42px; height: 42px; }
  .h-earth-3d-public-nav a { padding: 8px 10px; font-size: 0.78rem; }
  .h-earth-3d-title { font-size: clamp(2.1rem, 12vw, 4rem); }
  .h-earth-3d-world-shell { padding: 7px; }
  .h-earth-3d-world-stage { border-radius: 15px; }
  .h-earth-3d-fallback { padding: 22px; font-size: 0.76rem; }
  .h-earth-3d-readout-facts, .h-earth-3d-target-list { grid-template-columns: 1fr; }
  .h-earth-3d-action-button, .h-earth-3d-inline-copy-button { width: 100%; }
  .h-earth-3d-layer-4-projection-payload, .h-earth-3d-inspection-panel, .h-earth-3d-debug, .h-earth-3d-public-stage-receipt { max-height: 360px; font-size: 0.69rem; }
  .h-earth-3d-renderer-mount .h-earth-source-preview-caption, .h-earth-3d-renderer-mount [data-h-earth-source-preview-caption="true"] { left: 12px !important; top: 12px !important; max-width: calc(100% - 24px) !important; padding: 8px 9px !important; font-size: 0.66rem !important; }
  .h-earth-3d-renderer-mount .h-earth-render-label, .h-earth-3d-renderer-mount [data-h-earth-source-preview-label="true"] { max-width: min(190px, 78vw); font-size: 0.6rem; }
}

@media (max-width: 420px) {
  :root { --h-earth-stage-min-height: 360px; }
  .h-earth-3d-route-root { padding-left: 7px; padding-right: 7px; }
  .h-earth-3d-public-header { padding: 11px; }
  .h-earth-3d-brand-copy > span { font-size: 0.62rem; }
  .h-earth-3d-brand-copy > strong { font-size: 1rem; }
  .h-earth-3d-arrival-copy, .h-earth-3d-arrival-note, .h-earth-3d-public-control-strip, .h-earth-3d-panel, .h-earth-3d-readout-card, .h-earth-3d-layer-4-status-card { padding: 12px; }
  .h-earth-3d-title { font-size: clamp(2rem, 13vw, 3.45rem); }
  .h-earth-3d-fallback { padding: 16px; font-size: 0.7rem; }
  .h-earth-3d-renderer-mount .h-earth-source-preview-caption, .h-earth-3d-renderer-mount [data-h-earth-source-preview-caption="true"] { display: none; }
}
